import io
import pickle
class CustomPickler(pickle.Pickler):
    def persistent_id(self, obj):
        if isinstance(obj, str) and obj.startswith('DB:'):
            return ('database', obj[3:])
        return None
buf = io.BytesIO()
p = CustomPickler(buf)
p.dump('DB:user_123')
buf.seek(0)
loaded = pickle.load(buf)
print(loaded)

